use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let mut total = 0;
    for item in arr {
        let unit_price = item[0].as_i64().unwrap();
        let quantity = item[1].as_i64().unwrap();
        total += unit_price * quantity;
    }
    Value::from(total)
}
